1:package com.cockpitbench.navpilot.runtime;
2:
3:import java.util.Objects;
4:
5:/** Owns one navigation session while delegating storage and observation to injected boundaries. */
6:public final class NavigationRuntimeCoordinator implements AutoCloseable {
7:    private final NavigationObserverRegistry observers;
8:    private final NavigationSessionLedger ledger;
9:    private boolean attached;
10:    private boolean navigating;
11:
12:    public NavigationRuntimeCoordinator() {
13:        this(new NavigationObserverRegistry(), new NavigationSessionLedger(256));
14:    }
15:
16:    public NavigationRuntimeCoordinator(
17:            NavigationObserverRegistry observers,
18:            NavigationSessionLedger ledger) {
19:        this.observers = Objects.requireNonNull(observers, "observers");
20:        this.ledger = Objects.requireNonNull(ledger, "ledger");
21:    }
22:
23:    public synchronized void attach(long now) {
24:        if (attached) return;
25:        attached = true;
26:        record(new NavigationEvent(NavigationEvent.Type.ATTACHED, "car-context", now));
27:    }
28:
29:    public synchronized void detach(long now) {
30:        if (!attached) return;
31:        navigating = false;
32:        attached = false;
33:        record(new NavigationEvent(NavigationEvent.Type.STOPPED, "detached", now));
34:    }
35:
36:    public synchronized void start(long now) {
37:        if (!attached) throw new IllegalStateException("car context not attached");
38:        if (navigating) return;
39:        navigating = true;
40:        record(new NavigationEvent(NavigationEvent.Type.STARTED, "navigation", now));
41:    }
42:
43:    public synchronized void stop(long now) {
44:        if (!navigating) return;
45:        navigating = false;
46:        record(new NavigationEvent(NavigationEvent.Type.STOPPED, "requested", now));
47:    }
48:
49:    public synchronized boolean isAttached() { return attached; }
50:    public synchronized boolean isNavigating() { return navigating; }
51:    public NavigationObserverRegistry observers() { return observers; }
52:    public NavigationSessionLedger ledger() { return ledger; }
53:
54:    private void record(NavigationEvent event) {
55:        ledger.add(event);
56:        observers.publish(event);
57:    }
58:
59:    @Override public synchronized void close() {
60:        navigating = false;
61:        attached = false;
62:        observers.clear();
63:        ledger.clear();
64:    }
65:}
