232:                    mHandler.post(() -> {
233:                        view.setImageBitmap(bitmap);
234:                    });
235:                })
236:                .exceptionally(ex -> {
237:                    if (Log.isLoggable(TAG, Log.DEBUG)) {
238:                        Log.d(TAG, "Unable to fetch image for maneuver: " + imageReference);
239:                    }
240:                    return null;
241:                });
242:    }
