48:public class NavStateController {
49:    private static final String TAG = "Cluster.NavController";
50:
51:    private final Handler mHandler = new Handler();
52:
53:    private final View mNavigationState;
54:    private final LinearLayout mSectionManeuver;
55:    private final LinearLayout mSectionNavigation;
56:    private final LinearLayout mSectionServiceStatus;
57:
58:    private final ImageView mManeuver;
59:    private final ImageView mProvidedManeuver;
60:    private final LaneView mLane;
61:    private final LaneView mProvidedLane;
62:    private final TextView mDistance;
63:    private final TextView mSegment;
64:    private final TextView mEta;
65:    private final CueView mCue;
66:    private final Context mContext;
67:    private final ImageResolver mImageResolver;
68:
69:    /**
70:     * Creates a controller to coordinate updates to the views displaying navigation state
71:     * data.
72:     *
73:     * @param container {@link View} containing the navigation state views
74:     */
75:    public NavStateController(View container, ImageResolver imageResolver) {
76:        mNavigationState = container;
77:        mSectionManeuver = container.findViewById(R.id.section_maneuver);
78:        mSectionNavigation = container.findViewById(R.id.section_navigation);
79:        mSectionServiceStatus = container.findViewById(R.id.section_service_status);
80:
81:        mManeuver = container.findViewById(R.id.maneuver);
82:        mProvidedManeuver = container.findViewById(R.id.provided_maneuver);
83:        mLane = container.findViewById(R.id.lane);
84:        mProvidedLane = container.findViewById(R.id.provided_lane);
85:        mDistance = container.findViewById(R.id.distance);
86:        mSegment = container.findViewById(R.id.segment);
87:        mEta = container.findViewById(R.id.eta);
88:        mCue = container.findViewById(R.id.cue);
89:
90:        mContext = container.getContext();
91:        mImageResolver = imageResolver;
92:    }
93:
94:    public void hideNavigationStateInfo() {
95:        mNavigationState.setVisibility(View.INVISIBLE);
96:    }
97:
98:    public void showNavigationStateInfo() {
99:        mNavigationState.setVisibility(View.VISIBLE);
100:    }
101:
102:    /**
103:     * Updates views to reflect the provided navigation state
104:     */
105:    public void update(@Nullable NavigationStateProto state) {
106:        if (Log.isLoggable(TAG, Log.DEBUG)) {
107:            Log.d(TAG, "Updating nav state: " + state);
108:        }
109:
110:        if (state == null) {
111:            return;
112:        }
113:
114:        NavigationStateProto.ServiceStatus serviceStatus = state.getServiceStatus();
115:        if (serviceStatus == SERVICE_STATUS_UNSPECIFIED) {
116:            mSectionManeuver.setVisibility(View.INVISIBLE);
117:            mSectionNavigation.setVisibility(View.INVISIBLE);
118:            mSectionServiceStatus.setVisibility(View.INVISIBLE);
119:            return;
120:        } else if (serviceStatus == REROUTING) {
121:            mSectionManeuver.setVisibility(View.INVISIBLE);
122:            mSectionNavigation.setVisibility(View.INVISIBLE);
123:            mSectionServiceStatus.setVisibility(View.VISIBLE);
124:            return;
125:        } else {
126:            mSectionManeuver.setVisibility(View.VISIBLE);
127:            mSectionNavigation.setVisibility(View.VISIBLE);
128:            mSectionServiceStatus.setVisibility(View.GONE);
129:        }
130:
131:        Step step = state.getStepsCount() > 0 ? state.getSteps(0) : null;
132:
133:        // Get alpha based on is_imminent
134:        float alpha = (step != null && !step.getIsImminent())
135:                ? getAlphaFromResource(R.dimen.non_imminent_alpha)
136:                : 1f;
137:
138:        Destination destination = state.getDestinationsCount() > 0
139:                ? state.getDestinations(0) : null;
140:        Traffic traffic = destination != null ? destination.getTraffic() : null;
141:        String eta = destination != null
142:                ? destination.getFormattedDurationUntilArrival().isEmpty()
143:                ? formatEta(destination.getEstimatedTimeAtArrival())
144:                : destination.getFormattedDurationUntilArrival()
145:                : null;
146:        mEta.setText(eta);
147:        mEta.setTextColor(getTrafficColor(traffic));
148:        mManeuver.setImageDrawable(getManeuverIcon(step != null ? step.getManeuver() : null));
149:        setProvidedManeuverIcon(mProvidedManeuver, step != null
150:                ? step.getManeuver().hasIcon() ? step.getManeuver().getIcon() : null
151:                : null);
152:        mManeuver.setImageAlpha((int) (alpha * 255));
153:        mDistance.setText(formatDistance(step != null ? step.getDistance() : null));
154:        mDistance.setAlpha(alpha);
155:        mSegment.setText(getSegmentString(state.getCurrentRoad()));
156:        mCue.setCue(step != null ? step.getCue() : null, mImageResolver, alpha);
157:
158:        if (step != null && step.getLanesCount() > 0) {
159:            if (step.hasLanesImage()) {
160:                mProvidedLane.setLanes(step.getLanesImage(), mImageResolver);
161:                mProvidedLane.setVisibility(View.VISIBLE);
162:            }
163:
164:            mLane.setLanes(step.getLanesList(), alpha);
165:            mLane.setVisibility(View.VISIBLE);
166:        } else {
167:            mLane.setVisibility(View.GONE);
168:            mProvidedLane.setVisibility(View.GONE);
169:        }
170:
171:    }
172:
173:    /**
174:     * Get float value from dimens.xml, it only works for float format
175:     */
176:    private float getAlphaFromResource(int alphaId) {
177:        TypedValue typedValue = new TypedValue();
178:        mContext.getResources().getValue(alphaId, typedValue, true);
179:        return typedValue.getFloat();
180:    }
